local config = {
  ui_story_5054_50540101_1_dialog_content = "<color=#a8886f>As pétalas queimaram até virarem cinzas antes de atingirem o chão, uma lembrança da confusão pela qual este tranquilo jardim acabou de passar.</color>",
  ui_story_5054_50540101_2_dialog_content = "<color=#a8886f>As trilhas, ainda ladeadas por flores desabrochando em ambos os lados, cortam portas labirínticas e levam a um corredor com uma cúpula muito alta.</color>",
  ui_story_5054_50540101_3_dialog_content = "<color=#a8886f>Uma empregada colocou lanches em uma sala, depois se virou e saiu. Pouco depois, ouviu-se uma tagarelice do lado de fora da porta...</color>",
  ui_story_5054_50540101_4_option_content = "(escutar)",
  ui_story_5054_50540101_5_dialog_content = "Então, é realmente a princesa Veronica aí?",
  ui_story_5054_50540101_6_dialog_content = "É verdade, eu vi com meus próprios olhos.",
  ui_story_5054_50540101_7_dialog_content = "Esses caras parecem suspeitos. Por que Sua Alteza estaria com eles?",
  ui_story_5054_50540101_8_dialog_content = "Relaxe, Dona Rot está com Lady Joshua. Não é nossa preocupação.",
  ui_story_5054_50540101_9_dialog_content = "Mas é estranho, no entanto. A Sra. Rot, o Lorde da Cidade, não é a favorita? Por que ela não está na festa?",
  ui_story_5054_50540101_10_dialog_content = "Você não sabe? Senhora Joshua e a Sra. Rot são muito unidas, e foi o Lorde da Cidade quem disse à Sra. Rot para cuidar de Sua Senhoria.",
  ui_story_5054_50540101_11_dialog_content = "Mas se eles são tão apertados, por que Lady Joshua deliberadamente mandar a Sra. Rot embora?",
  ui_story_5054_50540101_12_dialog_content = "Sem chance! Ouvi dizer que a Sra. Rot não é apenas uma parente distante de Lady Joshua, mas o último aluno dela também!",
  ui_story_5054_50540101_13_option_content = "Parente distante...?",
  ui_story_5054_50540101_14_dialog_content = "Sim, mas provavelmente não há mais relações de sangue.",
  ui_story_5054_50540101_15_option_content = "Último aluno...?",
  ui_story_5054_50540101_16_dialog_content = "Sim. A Sra. Rot era supostamente uma criança prodígio, mas não tinha orientação.",
  ui_story_5054_50540101_17_dialog_content = "Seus pais procuraram Sir Caleb por meio de conexões e fortuitamente encontraram Lady Joshua.",
  ui_story_5054_50540101_18_dialog_content = "Senhora Joshua e a Sra. Rot se deu bem imediatamente, então ela a orientou por anos.",
  ui_story_5054_50540101_19_dialog_content = "Ei, quem está fazendo perguntas?",
  ui_story_5054_50540101_20_dialog_content = "Não foi você?",
  ui_story_5054_50540101_21_dialog_content = "Aham, shhh—",
  ui_story_5054_50540101_22_dialog_content = "As paredes têm ouvidos... Continuaremos com isso mais tarde.",
  ui_story_5054_50540102_1_dialog_content = "<color=#a8886f>As brisas que sopram rapidamente quebram folhas e pétalas frescas e deliciosas.</color>",
  ui_story_5054_50540102_2_dialog_content = "<color=#a8886f>Crunch!</color>",
  ui_story_5054_50540102_3_dialog_content = "<color=#a8886f>Uma carta com bordas queimadas faz um barulho seco e ensurdecedor quando pisada.</color>",
  ui_story_5054_50540102_4_dialog_content = "O que é isso?",
  ui_story_5054_50540102_5_dialog_content = "Encontrou algo, Caleb?",
  ui_story_5054_50540102_6_dialog_content = "Uma pilha de cartas queimadas, aparentemente pertencentes à minha irmã...",
  ui_story_5054_50540102_7_option_content = "(Pega um)",
  ui_story_5054_50540102_8_dialog_content = "<color=#a8886f>Algumas linhas de escrita elegante são vagamente discerníveis na folha carbonizada.</color>",
  ui_story_5054_50540102_9_dialog_content = "\"Filho de Montague...\"",
  ui_story_5054_50540102_10_dialog_content = "Conheço a caligrafia e a assinatura... Meu pai escreveu isso?!",
  ui_story_5054_50540102_11_dialog_content = "\"No final, não passo de um rato de biblioteca covarde.\"",
  ui_story_5054_50540102_12_dialog_content = "\"A única coisa que posso fazer é partir com...\"",
  ui_story_5054_50540102_13_dialog_content = "\"Espero que você e a criança vivam felizes para sempre.\"",
  ui_story_5054_50540102_14_dialog_content = "Quem é o filho de Montague?",
  ui_story_5054_50540102_15_dialog_content = "Sei lá.",
  ui_story_5054_50540102_16_dialog_content = "Meu pai era um estudioso compassivo. Eu não ficaria surpreso se ele patrocinasse os filhos de outras pessoas.",
  ui_story_5054_50540102_17_dialog_content = "Aham.",
  ui_story_5054_50540102_18_dialog_content = "<color=#a8886f>Schwartz solta uma tosse fraca, mas a urgência vem alta e clara.</color>",
  ui_story_5054_50540102_19_dialog_content = "Não vamos nos preocupar com isso e vamos embora!",
  ui_story_5054_50540103_1_dialog_content = "<color=#a8886f>Whoosh!</color>",
  ui_story_5054_50540103_2_dialog_content = "<color=#a8886f>Uma jovem ruiva aparece do nada e impede um jovem cavaleiro que corre em direção à praça principal.</color>",
  ui_story_5054_50540103_3_dialog_content = "(Vejo duas figuras bloqueando o caminho à frente...)",
  ui_story_5054_50540103_4_dialog_content = "Sharona?",
  ui_story_5054_50540103_5_dialog_content = "Desculpe, eu te conheço?",
  ui_story_5054_50540103_6_dialog_content = "Olhe para você nesse ridículo traje de cavaleiro! Eu gostaria de não ter reconhecido você, mas os chifres em sua cabeça tornaram difícil não reconhecê-lo.",
  ui_story_5054_50540103_7_dialog_content = "Quem é você?",
  ui_story_5054_50540103_8_dialog_content = "Você realmente não pode dizer?",
  ui_story_5054_50540103_9_dialog_content = "Ainda não verifiquei a última lista de procurados.",
  ui_story_5054_50540103_10_dialog_content = "<color=#a8886f>As chamas de repente se manifestam atrás da garota, mas depois se dispersam como uma respiração exalada.</color>",
  ui_story_5054_50540103_11_dialog_content = "Tudo bem, deixe-me contar uma história.",
  ui_story_5054_50540103_12_dialog_content = "Uma mãe com Dragonkin despertou deu à luz duas filhas. Sua herança a fez perder o controle e ela foi morta por sua família.",
  ui_story_5054_50540103_13_dialog_content = "Para proteger seu dragão prestes a nascer, a filha mais velha escolheu vagar até se estabelecer em Umbraton. A filha mais nova cresceu sem saber que sua mãe foi morta por sua tribo.",
  ui_story_5054_50540103_14_dialog_content = "Me desculpe, eu não ouvi essa história antes, mas tenho a sensação de que você é aquela filha mais velha.",
  ui_story_5054_50540103_15_dialog_content = "O que você está fazendo em Lumopolis? Você é responsável pelo que aconteceu na praça?",
  ui_story_5054_50540103_16_dialog_content = "Vejo que não lhe disseram absolutamente nada. Bem, fique à vontade para continuar servindo como fantoche de Lumopolis.",
  ui_story_5054_50540103_17_dialog_content = "<color=#a8886f>A garota ruiva abatida se vira, mas Sharona mira nela sem intenção de deixá-la ir embora.</color>",
  ui_story_5054_50540103_18_option_content = "Passando!",
  ui_story_5054_50540103_19_option_content = "Assassinos estão aqui agora!",
  ui_story_5054_50540103_20_dialog_content = "O quê?",
  ui_story_5054_50540103_21_dialog_content = "<color=#a8886f>A garota ruiva desaparece em um piscar de olhos, enquanto todos vocês passam correndo pelo confuso Sharona.</color>",
  ui_story_5054_50540201_1_dialog_content = "<color=#a8886f>Fitas coloridas, banners e decorações especiais fazem a cidade totalmente branca parecer muito diferente do normal. Você se esconde atrás de um enorme estandarte e foge de seus perseguidores.</color>",
  ui_story_5054_50540201_2_dialog_content = "<color=#a8886f>Apenas quando você está decidindo se quer sair, várias figuras param antes do banner...</color>",
  ui_story_5054_50540201_3_dialog_content = "Você não trouxe a Srta. Roshee com você hoje, Duque Troy?",
  ui_story_5054_50540201_4_dialog_content = "(Roshee? Não é o nome de infância de Michael?)",
  ui_story_5054_50540201_5_dialog_content = "Eu a instruí a ficar em casa e estudar. Ela pode participar de tal evento quando for mais velha.",
  ui_story_5054_50540201_6_dialog_content = "Aquela sua sobrinha Roshee vagabunda, caçadora de ladrões e criminosa, estava disposta a ficar em casa e estudar?",
  ui_story_5054_50540201_7_dialog_content = "Devo aprender técnicas de disciplina infantil com você algum dia, Duque Troy.",
  ui_story_5054_50540201_8_dialog_content = "Não é nada de especial. Embora Roshee não seja minha, ela é filha da minha irmã, com o sangue de Troy correndo em suas veias.",
  ui_story_5054_50540201_9_dialog_content = "As crianças saberiam o que fazer quando chegar a hora.",
  ui_story_5054_50540201_10_dialog_content = "Senhor...",
  ui_story_5054_50540201_11_dialog_content = "Por que você parece tão estressado?",
  ui_story_5054_50540201_12_dialog_content = "A senhorita Roshee fugiu!",
  ui_story_5054_50540201_13_dialog_content = "Vou deixar você ir, duque Troy. Vejo você no estande.",
  ui_story_5054_50540201_14_dialog_content = "Faremos, Duque Hermes.",
  ui_story_5054_50540201_15_dialog_content = "<color=#a8886f>Depois que Lachon vai embora, Otto fica sombrio.</color>",
  ui_story_5054_50540201_16_dialog_content = "Como você pode trazer isso à tona na frente de outras pessoas, seu lixo!",
  ui_story_5054_50540201_17_dialog_content = "Desculpe, senhor, estava com muita pressa... Não vai acontecer de novo!",
  ui_story_5054_50540201_18_dialog_content = "Não haverá uma próxima vez!",
  ui_story_5054_50540201_19_dialog_content = "Roshee mencionou para onde ela está indo?",
  ui_story_5054_50540201_20_dialog_content = "Não... Mas a empregada disse que recebeu um bilhete pela janela antes de sair.",
  ui_story_5054_50540201_21_dialog_content = "<color=#a8886f>Otto segue o servo até em casa, mas a serenidade é imediatamente interrompida por soldados apressados e moradores da cidade.</color>",
  ui_story_5054_50540202_1_dialog_content = "<color=#a8886f>Gritos intermitentes vêm da praça. Alguns fugitivos sortudos iniciam aeronaves em sua tentativa de deixar a cidade flutuante supostamente mais segura.</color>",
  ui_story_5054_50540202_2_dialog_content = "<color=#a8886f>Enquanto isso, em uma trilha quase imperceptível, você vê duas figuras familiares.</color>",
  ui_story_5054_50540202_3_dialog_content = "<color=#a8886f>A menina ruiva, Leona, com uma carta na mão, está conversando com alguém inesperadamente.</color>",
  ui_story_5054_50540202_4_dialog_content = "Alto!",
  ui_story_5054_50540202_5_dialog_content = "O quê?",
  ui_story_5054_50540202_6_dialog_content = "(Eles se conhecem?)",
  ui_story_5054_50540202_7_dialog_content = "Você incitou Roshee a fugir de casa?",
  ui_story_5054_50540202_8_dialog_content = "Se você está se referindo àquela garota que estava falando comigo, então você pegou a pessoa errada.",
  ui_story_5054_50540202_9_dialog_content = "Ela me confundiu com um Kartima e me pediu para entregar esta carta a Sharona Cartima.",
  ui_story_5054_50540202_10_dialog_content = "Passe-me a carta.",
  ui_story_5054_50540202_11_dialog_content = "Mesmo relutante em ajudá-la, tenho certeza de que não tenho que responder a um povo rude.",
  ui_story_5054_50540202_12_dialog_content = "Não acredito que tem alguém em Lumopolis que não me reconhece, Otto Troy...",
  ui_story_5054_50540202_13_dialog_content = "<color=#a8886f>Whoosh!</color>",
  ui_story_5054_50540202_14_dialog_content = "<color=#a8886f>Antes que Duke Troy termine, a garota ruiva põe fogo em um canto da carta.</color>",
  ui_story_5054_50540202_15_dialog_content = "O que? Prenda-a!",
  ui_story_5054_50540202_16_dialog_content = "<color=#a8886f>A carta em chamas passa por seus olhos e, antes de ser incinerada, você distingue parte da escrita...</color>",
  ui_story_5054_50540202_17_dialog_content = "\"O incidente do Eclipsite de um ano atrás... Nos bastidores... Duque Otto Troy... inacreditável... não pode ficar mais tempo...\"",
  ui_story_5054_50540202_18_dialog_content = "<color=#a8886f>Chiar...</color>",
  ui_story_5054_50540202_19_dialog_content = "<color=#a8886f>A carta se transforma em cinzas, desaparecendo das ruas imaculadas de Lumopolis, assim como no passado.</color>",
  ui_story_5054_50540203_1_dialog_content = "<color=#a8886f>Colidir...</color>",
  ui_story_5054_50540203_2_dialog_content = "<color=#a8886f>No pátio ao lado da estrada, uma torre desmorona repentinamente. A poeira cobre a vizinhança e obstrui a visão.</color>",
  ui_story_5054_50540203_3_dialog_content = "*Cof Cof*",
  ui_story_5054_50540203_4_dialog_content = "<color=#a8886f>De um vão entre os escombros, as tosses dos idosos quebram o silêncio.</color>",
  ui_story_5054_50540203_5_dialog_content = "(Quem é aquele na frente dele?)",
  ui_story_5054_50540203_6_dialog_content = "Você ainda se lembra de mim?",
  ui_story_5054_50540203_7_dialog_content = "<color=#a8886f>O velho olha para cima lentamente antes de olhar para outro lugar.</color>",
  ui_story_5054_50540203_8_dialog_content = "você não se lembra Leona? Vocês queriam quebrar o ovo de dragão na minha mão...",
  ui_story_5054_50540203_9_dialog_content = "Não, não você.",
  ui_story_5054_50540203_10_dialog_content = "<color=#a8886f>A garota congela como uma estátua, sem fala por uma longa pausa...</color>",
  ui_story_5054_50540203_11_dialog_content = "Heh, a última vez que ouvi algo tão absurdo, eu tinha apenas quatro, cinco anos. Agora, eu não posso ser influenciado tão facilmente.",
  ui_story_5054_50540203_12_dialog_content = "Mesmo se você continuar balbuciando para mim que \"Você não é o único a salvar os Kartimas\" como minha mãe, a quem você considerou louca...",
  ui_story_5054_50540203_13_dialog_content = "Não é você quem vai salvar os Kartimas... Nem Mime...",
  ui_story_5054_50540203_14_dialog_content = "Ela vai se mostrar em breve! Ela está vindo!",
  ui_story_5054_50540203_15_dialog_content = "<color=#a8886f>A ruiva torna a calar-se, mas apenas por um segundo, até que cai na gargalhada de pena e tristeza que ecoam no pátio vazio.</color>",
  ui_story_5054_50540203_16_dialog_content = "Hahaha! Hahaha-!",
  ui_story_5054_50540203_17_dialog_content = "Eu sabia que não deveria voltar pela humilhação.",
  ui_story_5054_50540203_18_dialog_content = "<color=#a8886f>Você deixa a ruína assim que pode ver. Entre os escombros, um idoso aguarda o salvador em sua mente.</color>",
  ui_story_5054_50540301_1_dialog_content = "<color=#a8886f>Barulhos de explosões, gritos, corações batendo e armas duras empalando objetos macios explodem ao redor...</color>",
  ui_story_5054_50540301_2_dialog_content = "<color=#a8886f>Asas gigantes levantam um vendaval após o outro, soprando poeira nos rostos das pessoas que fogem do local.</color>",
  ui_story_5054_50540301_3_dialog_content = "<color=#a8886f>Suor, lágrimas e sangue rapidamente dominam o cheiro do perfume usado por uma jovem nobre. Ela e um jovem nobre observam tudo se desenrolar com medo...</color>",
  ui_story_5054_50540301_4_option_content = "Por aqui, rápido!",
  ui_story_5054_50540301_5_dialog_content = "Obrigado por nos mostrar uma saída! B-Mas o que está acontecendo aqui?",
  ui_story_5054_50540301_6_dialog_content = "Insurreição! Uma insurreição premeditada!",
  ui_story_5054_50540301_7_dialog_content = "Meu Deus da Luz... Por que alguém faria isso em Lumopolis?",
  ui_story_5054_50540301_8_dialog_content = "Não se lembra das consequências para aqueles que se opuseram ao governo de Schwartz, senhorita?",
  ui_story_5054_50540301_9_dialog_content = "Casa Pyrrhus recentemente, depois Casa Gautier, e Casa Montague antes disso...",
  ui_story_5054_50540301_10_dialog_content = "Você quer dizer as casas exiladas?",
  ui_story_5054_50540301_11_dialog_content = "Oh meu... Ouvi dizer que há uma cabala secreta de sobreviventes planejando sua vingança...",
  ui_story_5054_50540301_12_dialog_content = "Isso é loucura! Todos eles enlouqueceram!",
  ui_story_5054_50540301_13_dialog_content = "A vingança é apenas um pretexto para aqueles que tentaram destronar! Cegar pela vingança apenas o tornará vulnerável à manipulação!",
  ui_story_5054_50540301_14_dialog_content = "(Cabala secreta? Destronar?)",
  ui_story_5054_50540301_15_dialog_content = "Agora não é hora de refletir sobre isso. Temos que correr!",
  ui_story_5054_50540301_16_dialog_content = "<color=#a8886f>A dupla sai antes que você possa perguntar qualquer coisa. Você olha na direção deles apenas para vê-los cercados por insurgentes...</color>",
  ui_story_5054_50540302_1_dialog_content = "<color=#a8886f>Você está familiarizado com a rota da praça de volta ao Schwartz Mansão. Você também não vai esquecer que havia uma torre no caminho que agora está reduzida a pó.</color>",
  ui_story_5054_50540302_2_dialog_content = "<color=#a8886f>Entre as pedras e escombros surge a voz rouca e excitada de um idoso.</color>",
  ui_story_5054_50540302_3_dialog_content = "Você! É você!",
  ui_story_5054_50540302_4_dialog_content = "(Quem é aquele na frente dele?)",
  ui_story_5054_50540302_5_dialog_content = "Você está finalmente aqui para me ver!",
  ui_story_5054_50540302_6_dialog_content = "Eu sou Sharona Cartima. Você me conhece?",
  ui_story_5054_50540302_7_dialog_content = "Sharona, que nome bonito... A profecia me deu a capacidade de reconhecê-lo, mas não revelaria que você tem um nome tão bonito.",
  ui_story_5054_50540302_8_dialog_content = "Profecia?",
  ui_story_5054_50540302_9_dialog_content = "<color=#a8886f>Os idosos examinam os arredores com cautela antes de falar em voz baixa.</color>",
  ui_story_5054_50540302_10_dialog_content = "No porão da minha antiga casa está uma relíquia de Kartima, uma grande katana chamada Azure Chama.",
  ui_story_5054_50540302_11_dialog_content = "Agora é seu. Pegar Azure Chama e termina o que é pra terminar!",
  ui_story_5054_50540302_12_dialog_content = "Azure Chama? Eu vi uma katana no escritório do tio Mime com o mesmo nome...",
  ui_story_5054_50540302_13_dialog_content = "Como aquele impostor ousa pegar o que não lhe pertence!",
  ui_story_5054_50540302_14_dialog_content = "Mas não se preocupe, não importa se ele manteve Azure Chama, pertence a você!",
  ui_story_5054_50540302_15_dialog_content = "Só você pode desbloquear seu poder!",
  ui_story_5054_50540302_16_dialog_content = "Vá, meu filho, rápido!",
  ui_story_5054_50540302_17_dialog_content = "<color=#a8886f>Sharon ainda está perdida, mas você sabe que daqui a doze anos, Comandante Sharona de Illumina segurará em suas mãos uma grande espada chamada Azure Chama.</color>"
}
return config
